import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64


PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry triplet_margin_loss_kernel(
    .param .u64 A,
    .param .u64 P,
    .param .u64 N,
    .param .u64 OUT,
    .param .u32 BATCH,
    .param .u32 DIM,
    .param .f32 MARGIN
)
{
    .reg .pred %p<27>;
    .reg .f32  %f<40>;
    .reg .b32  %r<80>;
    .reg .b64  %rd<20>;

    .shared .align 4 .b8 shared_pos[128];
    .shared .align 4 .b8 shared_neg[128];

    ld.param.u64 %rd1, [A];
    ld.param.u64 %rd2, [P];
    ld.param.u64 %rd3, [N];
    ld.param.u64 %rd4, [OUT];
    ld.param.u32 %r1,  [BATCH];
    ld.param.u32 %r2,  [DIM];
    ld.param.f32 %f1,  [MARGIN];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r3, %ctaid.x;
    setp.ge.s32 %p1, %r3, %r1;
    @%p1 bra DONE;

    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %ntid.x;

    // row_offset(elems) = row * dim
    mul.lo.s32 %r6, %r3, %r2;
    cvt.s64.s32 %rd5, %r6;
    shl.b64 %rd6, %rd5, 2;

    add.s64 %rd7, %rd1, %rd6;   // A row ptr
    add.s64 %rd8, %rd2, %rd6;   // P row ptr
    add.s64 %rd9, %rd3, %rd6;   // N row ptr

    mov.f32 %f2, 0f00000000;    // sum_pos
    mov.f32 %f3, 0f00000000;    // sum_neg

    // ---- vectorized main loop: process 4 elements at a time ----
    shr.u32 %r70, %r2, 2;       // quads = dim / 4
    shl.b32 %r71, %r70, 2;      // vec_covered = quads * 4

    mov.u32 %r7, %r4;           // vector index = tid

VEC_LOOP_START:
    setp.ge.s32 %p2, %r7, %r70;
    @%p2 bra VEC_LOOP_END;

    mul.wide.s32 %rd14, %r7, 16;
    add.s64 %rd15, %rd7, %rd14;
    add.s64 %rd16, %rd8, %rd14;
    add.s64 %rd17, %rd9, %rd14;

    ld.global.v4.f32 {%f4, %f5, %f6, %f7}, [%rd15];    // a0..a3
    ld.global.v4.f32 {%f8, %f9, %f10, %f11}, [%rd16];  // p0..p3
    ld.global.v4.f32 {%f12, %f13, %f14, %f15}, [%rd17]; // n0..n3

    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f2, %f16, %f16, %f2;
    sub.f32 %f17, %f4, %f12;
    fma.rn.f32 %f3, %f17, %f17, %f3;

    sub.f32 %f18, %f5, %f9;
    fma.rn.f32 %f2, %f18, %f18, %f2;
    sub.f32 %f19, %f5, %f13;
    fma.rn.f32 %f3, %f19, %f19, %f3;

    sub.f32 %f20, %f6, %f10;
    fma.rn.f32 %f2, %f20, %f20, %f2;
    sub.f32 %f21, %f6, %f14;
    fma.rn.f32 %f3, %f21, %f21, %f3;

    sub.f32 %f22, %f7, %f11;
    fma.rn.f32 %f2, %f22, %f22, %f2;
    sub.f32 %f23, %f7, %f15;
    fma.rn.f32 %f3, %f23, %f23, %f3;

    add.s32 %r7, %r7, %r5;
    bra VEC_LOOP_START;

VEC_LOOP_END:

    // ---- scalar tail loop for remaining elements ----
    add.s32 %r7, %r71, %r4;

LOOP_START:
    setp.ge.s32 %p2, %r7, %r2;
    @%p2 bra LOOP_END;

    mul.wide.s32 %rd10, %r7, 4;
    add.s64 %rd11, %rd7, %rd10;
    add.s64 %rd12, %rd8, %rd10;
    add.s64 %rd13, %rd9, %rd10;

    ld.global.f32 %f4, [%rd11]; // a
    ld.global.f32 %f5, [%rd12]; // p
    ld.global.f32 %f6, [%rd13]; // n

    sub.f32 %f7, %f4, %f5;
    fma.rn.f32 %f2, %f7, %f7, %f2;

    sub.f32 %f8, %f4, %f6;
    fma.rn.f32 %f3, %f8, %f8, %f3;

    add.s32 %r7, %r7, %r5;
    bra LOOP_START;

LOOP_END:

    // ---- warp-level reduction of sum_pos (%f2) / sum_neg (%f3) ----
    mov.b32 %r10, %f2;
    shfl.sync.down.b32 %r11|%p3, %r10, 16, 31, -1;
    mov.b32 %f9, %r11;
    add.f32 %f2, %f2, %f9;

    mov.b32 %r12, %f3;
    shfl.sync.down.b32 %r13|%p4, %r12, 16, 31, -1;
    mov.b32 %f10, %r13;
    add.f32 %f3, %f3, %f10;

    mov.b32 %r14, %f2;
    shfl.sync.down.b32 %r15|%p5, %r14, 8, 31, -1;
    mov.b32 %f11, %r15;
    add.f32 %f2, %f2, %f11;

    mov.b32 %r16, %f3;
    shfl.sync.down.b32 %r17|%p6, %r16, 8, 31, -1;
    mov.b32 %f12, %r17;
    add.f32 %f3, %f3, %f12;

    mov.b32 %r18, %f2;
    shfl.sync.down.b32 %r19|%p7, %r18, 4, 31, -1;
    mov.b32 %f13, %r19;
    add.f32 %f2, %f2, %f13;

    mov.b32 %r20, %f3;
    shfl.sync.down.b32 %r21|%p8, %r20, 4, 31, -1;
    mov.b32 %f14, %r21;
    add.f32 %f3, %f3, %f14;

    mov.b32 %r22, %f2;
    shfl.sync.down.b32 %r23|%p9, %r22, 2, 31, -1;
    mov.b32 %f15, %r23;
    add.f32 %f2, %f2, %f15;

    mov.b32 %r24, %f3;
    shfl.sync.down.b32 %r25|%p10, %r24, 2, 31, -1;
    mov.b32 %f16, %r25;
    add.f32 %f3, %f3, %f16;

    mov.b32 %r26, %f2;
    shfl.sync.down.b32 %r27|%p11, %r26, 1, 31, -1;
    mov.b32 %f17, %r27;
    add.f32 %f2, %f2, %f17;

    mov.b32 %r28, %f3;
    shfl.sync.down.b32 %r29|%p12, %r28, 1, 31, -1;
    mov.b32 %f18, %r29;
    add.f32 %f3, %f3, %f18;

    and.b32 %r30, %r4, 31;     // lane
    shr.u32 %r31, %r4, 5;      // warp id

    setp.ne.s32 %p13, %r30, 0;
    @%p13 bra SKIP_STORE;

    shl.b32 %r32, %r31, 2;
    mov.u32 %r33, shared_pos;
    add.s32 %r34, %r33, %r32;
    st.shared.f32 [%r34], %f2;

    mov.u32 %r35, shared_neg;
    add.s32 %r36, %r35, %r32;
    st.shared.f32 [%r36], %f3;

SKIP_STORE:
    bar.sync 0;

    setp.ne.s32 %p14, %r31, 0;
    @%p14 bra DONE;

    add.s32 %r37, %r5, 31;
    shr.u32 %r38, %r37, 5;     // num_warps = ceil(ntid/32)

    setp.ge.s32 %p15, %r30, %r38;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    @%p15 bra REDUCE2;

    shl.b32 %r39, %r30, 2;
    mov.u32 %r40, shared_pos;
    add.s32 %r41, %r40, %r39;
    ld.shared.f32 %f19, [%r41];

    mov.u32 %r42, shared_neg;
    add.s32 %r43, %r42, %r39;
    ld.shared.f32 %f20, [%r43];

REDUCE2:
    mov.b32 %r44, %f19;
    shfl.sync.down.b32 %r45|%p16, %r44, 16, 31, -1;
    mov.b32 %f21, %r45;
    add.f32 %f19, %f19, %f21;

    mov.b32 %r46, %f20;
    shfl.sync.down.b32 %r47|%p17, %r46, 16, 31, -1;
    mov.b32 %f22, %r47;
    add.f32 %f20, %f20, %f22;

    mov.b32 %r48, %f19;
    shfl.sync.down.b32 %r49|%p18, %r48, 8, 31, -1;
    mov.b32 %f23, %r49;
    add.f32 %f19, %f19, %f23;

    mov.b32 %r50, %f20;
    shfl.sync.down.b32 %r51|%p19, %r50, 8, 31, -1;
    mov.b32 %f24, %r51;
    add.f32 %f20, %f20, %f24;

    mov.b32 %r52, %f19;
    shfl.sync.down.b32 %r53|%p20, %r52, 4, 31, -1;
    mov.b32 %f25, %r53;
    add.f32 %f19, %f19, %f25;

    mov.b32 %r54, %f20;
    shfl.sync.down.b32 %r55|%p21, %r54, 4, 31, -1;
    mov.b32 %f26, %r55;
    add.f32 %f20, %f20, %f26;

    mov.b32 %r56, %f19;
    shfl.sync.down.b32 %r57|%p22, %r56, 2, 31, -1;
    mov.b32 %f27, %r57;
    add.f32 %f19, %f19, %f27;

    mov.b32 %r58, %f20;
    shfl.sync.down.b32 %r59|%p23, %r58, 2, 31, -1;
    mov.b32 %f28, %r59;
    add.f32 %f20, %f20, %f28;

    mov.b32 %r60, %f19;
    shfl.sync.down.b32 %r61|%p24, %r60, 1, 31, -1;
    mov.b32 %f29, %r61;
    add.f32 %f19, %f19, %f29;

    mov.b32 %r62, %f20;
    shfl.sync.down.b32 %r63|%p25, %r62, 1, 31, -1;
    mov.b32 %f30, %r63;
    add.f32 %f20, %f20, %f30;

