    sqrt.rn.f32 %f32, %f20;   // d_neg
    sub.f32 %f33, %f31, %f32;
    add.f32 %f34, %f33, %f1;
    max.f32 %f35, %f34, 0f00000000;

    atom.global.add.f32 %f36, [%rd4], %f35;

DONE:
    ret;
