_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """
    Looks up the compiled kernel entry point to make sure the embedded PTX
    is well-formed and the expected symbol exists.
    """
    module = _get_module()
    entry = module.function("triplet_margin_loss_kernel")
    if entry is None:
        raise RuntimeError(
            "triplet_margin_loss_kernel entry point not found in PTX module"
        )
    return entry


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using a hand-authored PTX kernel launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._module = _get_module()
        validate_generated_code()

    def forward(self, anchor, positive, negative):
        assert anchor.is_cuda and positive.is_cuda and negative.is_cuda, \
            "All inputs must be CUDA tensors"
        assert anchor.shape == positive.shape == negative.shape, \
            "anchor, positive, negative must have the same shape"
        assert anchor.dim() == 2, "Expect 2D tensors [batch, dim]"

        a = anchor.contiguous()
        p = positive.contiguous()
        n = negative.contiguous()

        if a.dtype != torch.float32:
            a = a.to(torch.float32)
        if p.dtype != torch.float32:
            p = p.to(torch.float32)
        if n.dtype != torch.float32:
            n = n.to(torch.float32)

        batch, dim = a.shape
        out_sum = torch.zeros((), device=a.device, dtype=torch.float32)

        threads = 256
        stream = torch.cuda.current_stream(a.device).cuda_stream

        self._module.launch(
            "triplet_margin_loss_kernel",
            grid=(batch, 1, 1),
            block=(threads, 1, 1),
            shared_mem_bytes=0,
            stream=stream,
            args=[
                u64(a.data_ptr()),
                u64(p.data_ptr()),
                u64(n.data_ptr()),
                u64(out_sum.data_ptr()),
                i32(int(batch)),
                i32(int(dim)),
                f32(self.margin),
            ],
        )

        return out_sum / float(batch)

