    Tensor gP = make_tensor(make_gmem_ptr(p_ptr), make_shape(dim), make_stride(Int<1>{}));
    Tensor gN = make_tensor(make_gmem_ptr(n_ptr), make_shape(dim), make_stride(Int<1>{}));

