        for (int offset = 16; offset > 0; offset >>= 1) {
            sum_pos += __shfl_down_sync(0xffffffff, sum_pos, offset);
            sum_neg += __shfl_down_sync(0xffffffff, sum_neg, offset);
        }

        if (lane == 0) {
            float d_pos = sqrtf(sum_pos);
            float d_neg = sqrtf(sum_neg);
            float loss = d_pos - d_neg + margin;
            loss = loss > 0.0f ? loss : 0.0f;
